1	// Acceptance tests for the change request:
2	//   "Give me a statement for a client. Put all their invoices in one place. Show the total they
3	//    still owe me."
4	//
5	// A client now has a STATEMENT. It is reached from the client's own detail page
6	// (client-detail-page, at /clients/<id>) through a control that opens it (client-statement-open) —
7	// the per-client drill-in surface the client specs already use. The statement (client-statement)
8	// gathers in ONE place EVERY invoice belonging to that client, drawn from ALL of the client's
9	// projects (an invoice belongs to a project, a project belongs to a client — see
10	// client-projects.spec.ts / all-invoices.spec.ts), in a table (client-statement-table). Each row
11	// (statement-invoice-row-<id>) surfaces, for that invoice: its id (statement-invoice-id), the
12	// amount billed (statement-invoice-amount), how much has been paid against it
13	// (statement-invoice-paid = the sum of its payments — see invoice-payments.spec.ts), how much is
14	// still left to pay on it (statement-invoice-due = amount MINUS what has been paid — the same
15	// after-payments remainder as invoice-due-amount.spec.ts), and what stage it is at
16	// (statement-invoice-status: DRAFT / SENT / PAID).
17	//
18	// The statement also shows the TOTAL the client still owes (client-outstanding-total). "Still owe"
19	// carries the app's established owed meaning (dashboard-outstanding-total / invoice-owed-sent-only
20	// .spec.ts): it counts only invoices that have actually been SENT and not yet paid, and it is net
21	// of payments — i.e. the sum of each sent-but-unpaid invoice's REMAINING balance. A DRAFT has not
22	// gone out, so it is not yet owed; a PAID invoice is already in, so it adds nothing; and another
23	// client's invoices never leak into this client's statement or total.
24	//
25	// Asserts ONLY through the UI (data-testid). Data is arranged via resetAndSeed, which honours
26	// clients { id, name, email }, projects { id, clientId, name }, invoices { id, projectId, amount,
27	// status } and payments { id, invoiceId, amount, date }. This change introduces NO new audit
28	// record, so nothing is asserted through the audit channel here.
29	//
30	// The money values are NEW anchors, not among the three the money-format spec pins exactly, so they
31	// are matched leniently — a leading "$" and a trailing ".00" both optional — exactly as the sibling
32	// invoice-due-amount / payment-amount anchors are. Status labels are matched case-insensitively
33	// (/^sent$/i etc.) as the other invoice-stage specs do. Amounts, paid figures, remainders and the
34	// resulting owed totals are chosen so no value is a substring of another, of a wrong total a buggy
35	// implementation would produce (e.g. one that forgot to subtract payments, or counted a draft, a
36	// paid invoice, or another client's invoice), so each assertion pins its own value. This test
37	// SHOULD FAIL before the change: there is no client statement today.
38	import { test, expect } from '@playwright/test';
39	import { resetAndSeed } from '../support/seed';
40	
41	// "$300.00", "300.00" or "300" all pass — the "$" and the ".00" cents are both optional. This is
42	// how the other NEW money anchors are asserted; exact presentation is pinned by money-format.spec.
43	function money(amount: number): RegExp {
44	  return new RegExp(`^\\$?${amount}(\\.00)?$`);
45	}
46	
47	// Reach a client's statement the way a user does: open the client from the list, then open the
48	// statement from the client's detail page. The concrete URL of the statement is the feature's own
49	// choice; the stable contract is client-statement-open leading to client-statement.
50	async function openStatement(page: import('@playwright/test').Page, clientId: number) {
51	  await page.goto('/clients');
52	  await page.getByTestId(`client-open-${clientId}`).click();
53	  await expect(page.getByTestId('client-detail-page')).toBeVisible();
54	  await page.getByTestId('client-statement-open').click();
55	  await expect(page.getByTestId('client-statement')).toBeVisible();
56	}
57	
58	test.describe('a client statement with all their invoices and the total still owed', () => {
59	  test('lists every invoice across the client\'s projects, each with amount, paid, due and stage', async ({ page }) => {
60	    await resetAndSeed({
61	      clients: [
62	        { id: 1, name: 'Acme Corp', email: 'ops@acme.example' },
63	        { id: 2, name: 'Globex', email: 'hello@globex.example' },
64	      ],
65	      projects: [
66	        // Two projects for client 1 — the statement must gather invoices from BOTH, in one place.
67	        { id: 1, clientId: 1, name: 'Website redesign' },
68	        { id: 2, clientId: 1, name: 'Mobile app' },
69	        // A project for a DIFFERENT client — its invoice must not appear on client 1's statement.
70	        { id: 3, clientId: 2, name: 'Warehouse automation' },
71	      ],
72	      invoices: [
73	        // Client 1, project 1: 500 billed, 200 paid -> 300 still due, still SENT (part paid).
74	        { id: 1, projectId: 1, amount: 500, status: 'SENT' },
75	        // Client 1, project 2 (a different project): 400 billed, 400 paid -> 0 due, PAID.
76	        { id: 2, projectId: 2, amount: 400, status: 'PAID' },
77	        // Client 2's invoice — must NOT appear on client 1's statement.
78	        { id: 3, projectId: 3, amount: 777, status: 'SENT' },
79	      ],
80	      payments: [
81	        { id: 1, invoiceId: 1, amount: 200, date: '2025-06-15' },
82	        { id: 2, invoiceId: 2, amount: 400, date: '2025-07-01' },
83	        // Belongs to client 2's invoice — must not touch client 1's figures.
84	        { id: 3, invoiceId: 3, amount: 777, date: '2025-02-02' },
85	      ],
86	    });
87	
88	    await openStatement(page, 1);
89	    await expect(page.getByTestId('client-statement-table')).toBeVisible();
90	
91	    // Invoice 1 (project 1): billed 500, 200 paid, 300 still due, stage SENT.
92	    const row1 = page.getByTestId('statement-invoice-row-1');
93	    await expect(row1).toBeVisible();
94	    await expect(row1.getByTestId('statement-invoice-id')).toContainText('1');
95	    await expect(row1.getByTestId('statement-invoice-amount')).toHaveText(money(500));
96	    await expect(row1.getByTestId('statement-invoice-paid')).toHaveText(money(200));
97	    await expect(row1.getByTestId('statement-invoice-due')).toHaveText(money(300));
98	    await expect(row1.getByTestId('statement-invoice-status')).toHaveText(/^sent$/i);
99	
100	    // Invoice 2 (a DIFFERENT project of the same client): billed 400, fully paid, 0 due, stage PAID.
101	    // Its presence is what makes the statement span every project, not just one.
102	    const row2 = page.getByTestId('statement-invoice-row-2');
103	    await expect(row2).toBeVisible();
104	    await expect(row2.getByTestId('statement-invoice-id')).toContainText('2');
105	    await expect(row2.getByTestId('statement-invoice-amount')).toHaveText(money(400));
106	    await expect(row2.getByTestId('statement-invoice-paid')).toHaveText(money(400));
107	    await expect(row2.getByTestId('statement-invoice-due')).toHaveText(money(0));
108	    await expect(row2.getByTestId('statement-invoice-status')).toHaveText(/^paid$/i);
109	
110	    // Client 2's invoice never leaks in: no third row, and exactly the client's own two rows.
111	    await expect(page.getByTestId('statement-invoice-row-3')).toHaveCount(0);
112	    await expect(page.getByTestId('statement-invoice-amount')).toHaveCount(2);
113	
114	    // Still owed = only the sent-but-unpaid remainder: invoice 1's 300 (invoice 2 is paid -> 0).
115	    const total = page.getByTestId('client-outstanding-total');
116	    await expect(total).toBeVisible();
117	    await expect(total).toContainText('300');
118	    // Not 500 (would mean invoice 1's 200 payment was not subtracted).
119	    await expect(total).not.toContainText('500');
120	    // Not 900 (would mean the full billed amounts of both were summed, ignoring payments).
121	    await expect(total).not.toContainText('900');
122	    // Not the other client's 777.
123	    await expect(total).not.toContainText('777');
124	  });
125	
126	  test('the total still owed is the sum of what remains on sent invoices, net of payments', async ({ page }) => {
127	    await resetAndSeed({
128	      clients: [
129	        { id: 1, name: 'Acme Corp', email: 'ops@acme.example' },
130	        { id: 2, name: 'Globex', email: 'hello@globex.example' },
131	      ],
132	      projects: [
133	        { id: 1, clientId: 1, name: 'Website redesign' },
134	        { id: 2, clientId: 1, name: 'Mobile app' },
135	        { id: 3, clientId: 2, name: 'Warehouse automation' },
136	      ],
137	      invoices: [
138	        // Two SENT invoices, each PART paid, on two different projects of client 1:
139	        //   500 - 200 = 300 still owed, and 400 - 150 = 250 still owed.
140	        { id: 1, projectId: 1, amount: 500, status: 'SENT' },
141	        { id: 2, projectId: 2, amount: 400, status: 'SENT' },
