158	    await expect(page.getByTestId('statement-invoice-row-1').getByTestId('statement-invoice-due')).toHaveText(money(300));
159	    await expect(page.getByTestId('statement-invoice-row-2').getByTestId('statement-invoice-due')).toHaveText(money(250));
160	    await expect(page.getByTestId('statement-invoice-row-3').getByTestId('statement-invoice-due')).toHaveText(money(0));
161	    // Client 2's invoice is not even on the statement.
162	    await expect(page.getByTestId('statement-invoice-row-4')).toHaveCount(0);
163	
