168	    await expect(total).not.toContainText('900');
169	    // Not 990 (500 + 400 + 90, also counting the already-paid invoice at its full amount).
170	    await expect(total).not.toContainText('990');
171	    // Not 640 (550 + 90, counting the paid invoice on top of the correct remainder).
172	    await expect(total).not.toContainText('640');
